std::vector<Polygon2d> faces;
Arrangement2::Face_circulator fc = arr.faces_begin();
do {
    if (!arr.is_unbounded(fc)) {
        Polygon2d poly;
        bool has_outer_boundary = false;

        // Extract the outer boundary of the face
        Arrangement2::Halfedge_circulator hc = fc->outer_boundary_halfedges_begin();
        if (hc != nullptr) {
            has_outer_boundary = true;
            do {
                poly.push_back(arr.halfedge_source(hc));
                ++hc;
            } while (hc != Arrangement2::Halfedge_circulator());
        }

        if (has_outer_boundary) {
            faces.push_back(poly);
        }
    }
} while (++fc != arr.faces_begin());

return faces;
// END_CODE

